enum Ex {
  Lit(value: Int),
  Neg(inner: Ex),
  Add(lhs: Ex, rhs: Ex),
  Sub(lhs: Ex, rhs: Ex),
  Mul(lhs: Ex, rhs: Ex),
  Div(lhs: Ex, rhs: Ex),
}

type Parsed { tree: Ex, next: Int }

fn char_at(cs: List[Str], pos: Int) -> Str {
  return cs.get_or(pos, "")
}

fn skip_spaces(cs: List[Str], pos: Int) -> Int {
  if char_at(cs, pos) == " " {
    return skip_spaces(cs, pos + 1)
  }
  return pos
}

fn digit_value(c: Str) -> Int {
  if c.is_empty() {
    return -1
  }
  return "0123456789".index_of(c).unwrap_or(-1)
}

fn read_number(cs: List[Str], pos: Int, acc: Int) -> Parsed {
  let d = digit_value(char_at(cs, pos))
  if d >= 0 {
    return read_number(cs, pos + 1, acc * 10 + d)
  }
  return Parsed { tree: Ex.Lit(value: acc), next: pos }
}

fn parse_atom(cs: List[Str], pos: Int) -> Result[Parsed, Str] {
  let c = char_at(cs, pos)
  if c == "(" {
    let inner = parse_sum(cs, pos + 1)?
    let close = skip_spaces(cs, inner.next)
    if char_at(cs, close) == ")" {
      return Ok(Parsed { tree: inner.tree, next: close + 1 })
    }
    return Err("syntax error")
  }
  if digit_value(c) >= 0 {
    return Ok(read_number(cs, pos, 0))
  }
  return Err("syntax error")
}

fn parse_unary(cs: List[Str], pos: Int) -> Result[Parsed, Str] {
  let p = skip_spaces(cs, pos)
  if char_at(cs, p) == "-" {
    let inner = parse_unary(cs, p + 1)?
    return Ok(Parsed { tree: Ex.Neg(inner: inner.tree), next: inner.next })
  }
  return parse_atom(cs, p)
}

fn term_rest(cs: List[Str], lhs: Ex, pos: Int) -> Result[Parsed, Str] {
  let p = skip_spaces(cs, pos)
  let op = char_at(cs, p)
  if op == "*" or op == "/" {
    let rhs = parse_unary(cs, p + 1)?
    let node = match op == "*" {
      true => Ex.Mul(lhs: lhs, rhs: rhs.tree),
      false => Ex.Div(lhs: lhs, rhs: rhs.tree),
    }
    return term_rest(cs, node, rhs.next)
  }
  return Ok(Parsed { tree: lhs, next: p })
}

fn parse_term(cs: List[Str], pos: Int) -> Result[Parsed, Str] {
  let first = parse_unary(cs, pos)?
  return term_rest(cs, first.tree, first.next)
}

fn sum_rest(cs: List[Str], lhs: Ex, pos: Int) -> Result[Parsed, Str] {
  let p = skip_spaces(cs, pos)
  let op = char_at(cs, p)
  if op == "+" or op == "-" {
    let rhs = parse_term(cs, p + 1)?
    let node = match op == "+" {
      true => Ex.Add(lhs: lhs, rhs: rhs.tree),
      false => Ex.Sub(lhs: lhs, rhs: rhs.tree),
    }
    return sum_rest(cs, node, rhs.next)
  }
  return Ok(Parsed { tree: lhs, next: p })
}

fn parse_sum(cs: List[Str], pos: Int) -> Result[Parsed, Str] {
  let first = parse_term(cs, pos)?
  return sum_rest(cs, first.tree, first.next)
}

fn evaluate(e: Ex) -> Result[Int, Str] {
  match e {
    Ex.Lit(value) => { return Ok(value) },
    Ex.Neg(inner) => {
      let v = evaluate(inner)?
      return Ok(0 - v)
    },
    Ex.Add(lhs, rhs) => {
      let a = evaluate(lhs)?
      let b = evaluate(rhs)?
      return Ok(a + b)
    },
    Ex.Sub(lhs, rhs) => {
      let a = evaluate(lhs)?
      let b = evaluate(rhs)?
      return Ok(a - b)
    },
    Ex.Mul(lhs, rhs) => {
      let a = evaluate(lhs)?
      let b = evaluate(rhs)?
      return Ok(a * b)
    },
    Ex.Div(lhs, rhs) => {
      let a = evaluate(lhs)?
      let b = evaluate(rhs)?
      if b == 0 {
        return Err("division by zero")
      }
      return Ok(a / b)
    },
  }
  return Ok(0)
}

pub fn calc(expr: Str) -> Result[Int, Str] {
  let cs = expr.chars()
  let parsed = parse_sum(cs, 0)?
  if skip_spaces(cs, parsed.next) != cs.len() {
    return Err("syntax error")
  }
  return evaluate(parsed.tree)
}
